128→    }
129→
130→    // Generate deterministic weights based on strategy
131→    const dimensions = jdAnalysis.evaluation_dimensions;
132→    const priorities: Set<string> = new Set((jdAnalysis.inferred_priorities || []).map((p: string) => p.toLowerCase()));
133→    
134→    const rawWeights: Record<string, number> = {};
135→    
136→    if (weightStrategy === "equal") {
137→      // Equal weight for all dimensions
138→      for (const dim of dimensions) rawWeights[dim.key] = 1.0;
139→    } else if (weightStrategy === "custom" && Object.keys(weightOverrides).length > 0) {
140→      // Use admin-specified overrides, default to 1.0 for unspecified
141→      for (const dim of dimensions) {
142→        rawWeights[dim.key] = weightOverrides[dim.key] ?? 1.0;
143→      }
144→    } else {
145→      // priority_boosted (default)
146→      const criticalKeys = new Set<string>();
147→      for (const dim of dimensions) {
148→        const keyLower = dim.key.toLowerCase();
149→        const labelLower = dim.label.toLowerCase();
150→        if (keyLower.includes("skill") || keyLower.includes("tool") || keyLower.includes("experience")) {
151→          criticalKeys.add(dim.key);
152→        }
153→        for (const p of priorities) {
154→          if (labelLower.includes(p) || p.includes(labelLower)) {
155→            criticalKeys.add(dim.key);
156→          }
157→        }
158→      }
159→      for (const dim of dimensions) {
160→        rawWeights[dim.key] = criticalKeys.has(dim.key) ? 2.0 : 1.0;
161→      }
162→    }
163→
164→    // Normalize to sum to 1.0 with min 0.05 and max 0.50
165→    const totalRaw = Object.values(rawWeights).reduce((a, b) => a + b, 0);
166→    const weights: Record<string, number> = {};
167→    for (const [key, raw] of Object.entries(rawWeights)) {
168→      let normalized = raw / totalRaw;
169→      normalized = Math.max(0.05, Math.min(0.50, normalized));
170→      weights[key] = normalized;
171→    }
172→    // Re-normalize after clamping
173→    const totalClamped = Object.values(weights).reduce((a, b) => a + b, 0);
174→    for (const key of Object.keys(weights)) {
175→      weights[key] = Math.round((weights[key] / totalClamped) * 1000) / 1000;
176→    }
177→    // Fix rounding to exactly 1.0
178→    const finalTotal = Object.values(weights).reduce((a, b) => a + b, 0);
179→    const firstKey = Object.keys(weights)[0];
180→    if (firstKey) {
181→      weights[firstKey] = Math.round((weights[firstKey] + (1.0 - finalTotal)) * 1000) / 1000;
182→    }
183→
184→    // Generate JD embedding
185→    const embeddingResponse = await fetch("https://api.openai.com/v1/embeddings", {
186→      method: "POST",
187→      headers: {
188→        Authorization: `Bearer ${OPENAI_API_KEY}`,
