200→
201→    const embeddingData = await embeddingResponse.json();
202→    const jdEmbedding = embeddingData.data?.[0]?.embedding;
203→
204→    // Store everything
205→    const { error: updateError } = await supabase
206→      .from("jobs")
207→      .update({
208→        jd_analysis_json: jdAnalysis,
209→        dynamic_weights_json: weights,
210→        jd_embedding: JSON.stringify(jdEmbedding),
211→      } as any)
212→      .eq("id", job_id);
213→
214→    if (updateError) throw new Error(`Failed to save JD analysis: ${updateError.message}`);
215→
216→    console.log(`JD analysis complete for job ${job_id}: ${dimensions.length} dimensions, ${Object.keys(weights).length} weights`);
217→
218→    return new Response(
219→      JSON.stringify({
220→        success: true,
221→        jd_analysis: jdAnalysis,
222→        dynamic_weights: weights,
223→      }),
224→      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
225→    );
226→  } catch (err) {
227→    console.error("analyze-jd error:", err);
228→    await logSystemError({
229→      function_name: "analyze-jd",
230→      error_type: "JD_ANALYSIS_ERROR",
