236→    await logSystemError({ function_name: "rank-resumes", error_type: "PARSE_INVOKE", severity: "warning", error_message: errorToMessage(err), error_stack: errorToStack(err), resume_id: resumeId, job_id: jobId, user_id: userId });
237→  }
238→
239→  // Step 2: Re-fetch resume after parsing
240→  const { data: resume } = await supabase.from("resumes").select("*").eq("id", resumeId).single();
241→  if (!resume) {
242→    console.error(`Resume ${resumeId} not found after parsing`);
243→    return false;
244→  }
245→
246→  const rawText = resume.parsed_text || "";
247→  const parsedJson = resume.parsed_json;
248→
249→  // Step 3: Check if we have enough content to score
250→  const hasUsefulParsedJson = parsedJson && (
251→    (Array.isArray(parsedJson.skills_with_evidence) && parsedJson.skills_with_evidence.length > 0) ||
252→    (Array.isArray(parsedJson.roles_with_dates) && parsedJson.roles_with_dates.length > 0) ||
253→    (Array.isArray(parsedJson.education) && parsedJson.education.length > 0)
254→  );
255→  if (rawText.trim().length < 50 && !hasUsefulParsedJson) {
256→    console.warn(`Resume ${resumeId}: insufficient content after parsing, inserting zero score`);
257→    const summaryMsg = resume.status === "failed"
258→      ? "Could not extract text from this file. It may be image-based or have unsupported formatting. Please re-upload a text-based PDF or DOCX file."
