318→          Object.assign(categoryScores, retryScores);
319→          overallScore = 0;
320→          const retryKeyMap = new Map<string, any>();
321→          for (const [k, v] of Object.entries(retryScores)) retryKeyMap.set(normalizeKey(k), v);
322→          for (const dim of dimensions) {
323→            const weight = dynamicWeights[dim.key] ?? 0;
324→            const scoreEntry = retryScores[dim.key] || retryKeyMap.get(normalizeKey(dim.key));
325→            overallScore += (scoreEntry?.score ?? 0) * weight;
326→          }
327→          if (overallScore === 0 && Object.keys(retryScores).length > 0) {
328→            const rs = Object.values(retryScores).map((v: any) => v?.score ?? 0).filter((s: number) => s > 0);
329→            if (rs.length > 0) overallScore = rs.reduce((a: number, b: number) => a + b, 0) / rs.length;
330→          }
331→          overallScore = Math.round(Math.max(0, Math.min(100, overallScore)) * 100) / 100;
332→        }
333→      } catch (retryErr) {
334→        console.error(`Retry scoring failed for ${resumeId}:`, retryErr);
335→      }
336→    }
337→
338→    let hardFit = deepResult.hard_fit !== false;
339→    const missingCritical = deepResult.missing_critical_must_haves || [];
