349→      await supabase.from("resumes").update({ candidate_name: deepResult.candidate_name, status: "done" }).eq("id", resumeId);
350→    } else {
351→      await supabase.from("resumes").update({ status: "done" }).eq("id", resumeId);
352→    }
353→
354→    const { data: existingResult } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
355→    const resultData = {
356→      resume_id: resumeId, job_id: jobId, scoring_version: `v7-algo${cfg.algorithm_version ?? 1}`,
357→      overall_score: overallScore, hard_fit: hardFit,
358→      confidence: deepResult.confidence ?? 0,
359→      category_scores_json: categoryScores,
