377→    } else {
378→      await supabase.from("results").insert(resultData as any);
379→    }
380→    console.log(`Resume ${resumeId} scored: overall=${overallScore}, hardFit=${hardFit}`);
381→    return true;
382→
383→  } catch (err) {
