54→// ── BT/ET PDF text extraction ───────────────────────────────
55→function extractPdfText(bytes: Uint8Array): string {
56→  const raw = new TextDecoder("latin1").decode(bytes);
57→  const textChunks: string[] = [];
58→  const btEtRegex = /BT\s([\s\S]*?)ET/g;
59→  let block;
60→  while ((block = btEtRegex.exec(raw)) !== null) {
61→    const parenRegex = /\(([^)]*)\)/g;
62→    let match;
63→    while ((match = parenRegex.exec(block[1])) !== null) {
64→      const decoded = match[1]
65→        .replace(/\\n/g, "\n").replace(/\\r/g, "\r").replace(/\\t/g, "\t")
66→        .replace(/\\\\/g, "\\").replace(/\\\(/g, "(").replace(/\\\)/g, ")");
67→      if (decoded.trim()) textChunks.push(decoded);
68→    }
69→    const tjRegex = /\[([^\]]*)\]\s*TJ|(\([^)]*\))\s*Tj/g;
70→    let tjMatch;
71→    while ((tjMatch = tjRegex.exec(block[1])) !== null) {
72→      const content = tjMatch[1] || tjMatch[2] || "";
73→      const innerParen = /\(([^)]*)\)/g;
74→      let ip;
75→      while ((ip = innerParen.exec(content)) !== null) {
76→        if (ip[1].trim()) textChunks.push(ip[1]);
77→      }
78→    }
79→  }
80→  return textChunks.join(" ").replace(/\s+/g, " ").trim().slice(0, 15000);

